pub struct RuleCacheConditions {
    uncacheable: bool,
    font_size: Option<NonNegativeLength>,
    line_height: Option<NonNegativeLength>,
    writing_mode: Option<WritingMode>,
    color_scheme: Option<ColorSchemeFlags>,
}

fn matches(&self, cached_style: &ComputedValues, style: &StyleBuilder) -> bool {
        if cached_style.effective_zoom != style.effective_zoom {
            return false;
        }

        if cached_style
            .flags
            .intersects(ComputedValueFlags::IS_IN_APPEARANCE_BASE_SUBTREE)
            != style
                .flags()
                .intersects(ComputedValueFlags::IS_IN_APPEARANCE_BASE_SUBTREE)
        {
            return false;
        }

        if let Some(fs) = self.font_size
            && style.get_font().slow_clone_font_size().computed_size != fs
        {
            return false;
        }

        if let Some(lh) = self.line_height {
            let new_line_height =
                style
                    .device
                    .calc_line_height(style.get_font(), style.writing_mode, None);
            if new_line_height != lh {
                return false;
            }
        }

        if self
            .color_scheme
            .is_some_and(|cs| style.get_inherited_ui().color_scheme_bits() != cs)
        {
            return false;
        }

        if self.writing_mode.is_some_and(|wm| style.writing_mode != wm) {
            return false;
        }

        true
    }
}

pub fn find(&self, guards: &StylesheetGuards, context: &Context) -> Option<&ComputedValues> {
        // A pseudo-element with property restrictions can result in different
        // computed values if it's also used for a non-pseudo.
        if context
            .builder
            .pseudo
            .is_some_and(|p| !p.property_restriction().is_empty())
        {
            return None;
        }

        if context
            .included_cascade_flags
            .contains(RuleCascadeFlags::STARTING_STYLE)
        {
            // We don't want to cache nor include starting-style rules.
            return None;
        }

        let rules = context.builder.rules.as_ref();
        let rules = Self::get_rule_node_for_cache(guards, rules)?;
        let cached_values = self.map.get(rules)?;

        for (conditions, values) in cached_values.iter() {
            if conditions.matches(values, &context.builder) {
                debug!("Using cached reset style with conditions {:?}", conditions);
                return Some(&**values);
            }
        }
        None
    }


pub fn insert_if_possible(
        &mut self,
        guards: &StylesheetGuards,
        style: &Arc<ComputedValues>,
        pseudo: Option<&PseudoElement>,
        inputs: &CascadeInputs,
        conditions: &RuleCacheConditions,
    ) -> bool {
        if !conditions.cacheable() {
            return false;
        }

        // A pseudo-element with property restrictions can result in different computed values if
        // it's also used for a non-pseudo.
        // TODO: we could consider inserting them and just checking the builder like we do for zoom.
        if pseudo.is_some_and(|p| !p.property_restriction().is_empty()) {
            return false;
        }

        // Don't insert @starting-style styles in the cache, for the same reason.
        if inputs
            .included_cascade_flags
            .contains(RuleCascadeFlags::STARTING_STYLE)
        {
            return false;
        }

        let rules = style.rules.as_ref();
        let rules = match Self::get_rule_node_for_cache(guards, rules) {
            Some(r) => r.clone(),
            None => return false,
        };

        debug!(
            "Inserting cached reset style with conditions {:?}",
            conditions
        );
        let cached_conditions = CachedConditions {
            writing_mode: conditions.writing_mode,
            font_size: conditions.font_size,
            line_height: conditions.line_height,
            color_scheme: conditions.color_scheme,
        };
        self.map
            .entry(rules)
            .or_default()
            .push((cached_conditions, style.clone()));
        true
    }
}

pub fn have_shareable_element_dependent_functions<E>(
    target: &StyleSharingTarget<E>,
    candidate: &StyleSharingCandidate<E>,
) -> bool
where
    E: TElement,
{
    let borrowed_data = candidate.element.borrow_data().unwrap();
    let styles = &borrowed_data.styles;

    if styles.uses_tree_counting_function(TreeCountingFunction::SiblingIndex) {
        // Two elements with the same parent will always have a different index.
        return false;
    }

    if styles.uses_tree_counting_function(TreeCountingFunction::SiblingCount)
        && target.parent_element() != candidate.parent_element()
    {
        return false;
    }

    if styles.uses_element_scoped_random() {
        // Two elements will always have different element-scoped random values.
        return false;
    }

    true
}

pub struct TreeCountingCaches {
    /// A cache of element sibling-index() values.
    pub sibling_index: FxHashMap<OpaqueElement, u32>,
    /// A cache of element sibling-count() values, keyed by the element's parent node.
    pub sibling_count: FxHashMap<OpaqueNode, u32>,
}

impl TreeCountingCaches {
    /// Look up the tree-counting function values for the given element. If the element and
    /// its parent node are not cached, the values are computed and stored.
    pub fn get_or_compute(&mut self, element_context: &dyn ElementContext) -> TreeCountingResult {
        let (Some(target), Some(parent)) = (
            element_context.opaque_element(),
            element_context.opaque_parent(),
        ) else {
            return TreeCountingResult::default();
        };

        // Lookup from the index and count caches
        let cached_index = self.sibling_index.get(&target).copied();
        let cached_count = self.sibling_count.get(&parent).copied();
        if let (Some(index), Some(count)) = (cached_index, cached_count) {
            return TreeCountingResult::new(index, count);
        }

        // Compute the sibling index and sibling count for the element,
        // inserting into the caches as it traverses through its siblings.
        element_context.get_tree_counting_result(self)
    }
}

fn try_to_use_cached_reset_properties(
        &self,
        context: &mut computed::Context<'a>,
        cache: Option<&'a RuleCache>,
        guards: &StylesheetGuards,
    ) -> bool {
        let style = match self.first_line_reparenting {
            FirstLineReparenting::Yes { style_to_reparent } => style_to_reparent,
            FirstLineReparenting::No => {
                let Some(cache) = cache else { return false };
                let Some(style) = cache.find(guards, context) else {
                    return false;
                };
                style
            },
        };

        context.builder.copy_reset_from(style);

        // We're using the same reset style as another element, and we'll skip
        // applying the relevant properties. So we need to do the relevant
        // bookkeeping here to keep these bits correct.
        //
        // Note that the border/background properties are non-inherited, so we
        // don't need to do anything else other than just copying the bits over.
        //
        // When using this optimization, we also need to copy whether the old
        // style specified viewport units / used font-relative lengths, this one
        // would as well.  It matches the same rules, so it is the right thing
        // to do anyways, even if it's only used on inherited properties.
        let bits_to_copy = ComputedValueFlags::HAS_AUTHOR_OR_USER_SPECIFIED_BORDER_BACKGROUND
            | ComputedValueFlags::HAS_AUTHOR_OR_USER_SPECIFIED_GRID_AUTO_FLOW
            | ComputedValueFlags::DEPENDS_ON_SELF_FONT_METRICS
            | ComputedValueFlags::DEPENDS_ON_INHERITED_FONT_METRICS
            | ComputedValueFlags::IS_IN_APPEARANCE_BASE_SUBTREE
            | ComputedValueFlags::USES_CONTAINER_UNITS
            | ComputedValueFlags::USES_VIEWPORT_UNITS
            | ComputedValueFlags::USES_FONT_OR_WM_RELATIVE_UNITS
            | ComputedValueFlags::DEPENDS_ON_CONTAINER_STYLE_QUERY
            | ComputedValueFlags::USES_SIBLING_COUNT
            | ComputedValueFlags::USES_SIBLING_INDEX
            | ComputedValueFlags::USES_VISITED_DEPENDENT_PROPERTIES
            | ComputedValueFlags::USES_ELEMENT_SCOPED_RANDOM;
        context.builder.add_flags(style.flags & bits_to_copy);

        true
    }
